<?php $pageTitle='Order Management'; require '../includes/functions.php'; require_admin(); if(isset($_GET['approve_file'])){$pdo->prepare("UPDATE uploaded_files SET status='Print Ready' WHERE id=?")->execute([$_GET['approve_file']]);redirect('orders.php');} if($_SERVER['REQUEST_METHOD']==='POST'){$pdo->prepare('UPDATE orders SET status=? WHERE id=?')->execute([$_POST['status'],$_POST['id']]);$pdo->prepare('INSERT INTO notifications (user_id,message) SELECT user_id,? FROM orders WHERE id=?')->execute(['Your order status is now '.$_POST['status'],$_POST['id']]);redirect('orders.php');} $orders=$pdo->query('SELECT * FROM orders ORDER BY id DESC')->fetchAll(); require '_header.php'; ?>
<h1 class="fw-bold mb-4">Order Management</h1><div class="table-responsive"><table class="table bg-white"><thead><tr><th>Invoice</th><th>Customer</th><th>Total</th><th>Status</th><th>Files</th><th>Action</th></tr></thead><tbody><?php foreach($orders as $o): ?><tr><td><?= e($o['invoice_no']) ?></td><td><?= e($o['customer_name']) ?></td><td><?= money($o['total_amount']) ?></td><td><?= status_badge($o['status']) ?></td><td><?php $f=$pdo->prepare('SELECT * FROM uploaded_files WHERE order_id=?');$f->execute([$o['id']]);foreach($f as $file): ?><a href="../<?= e($file['file_path']) ?>" download><?= e($file['original_name']) ?></a> <span class="badge bg-secondary"><?= e($file['status']) ?></span> <a class="small" href="?approve_file=<?= $file['id'] ?>">Approve</a><br><?php endforeach; ?></td><td><form method="post" class="d-flex gap-1"><input type="hidden" name="id" value="<?= $o['id'] ?>"><select name="status" class="form-select form-select-sm"><?php foreach(['Pending','Confirmed','Designing','Printing','Ready for Pickup','Completed','Cancelled'] as $s): ?><option <?= $o['status']==$s?'selected':'' ?>><?= $s ?></option><?php endforeach; ?></select><button class="btn btn-sm btn-red">Update</button><a class="btn btn-sm btn-yellow" href="receipt.php?id=<?= $o['id'] ?>">Print</a></form></td></tr><?php endforeach; ?></tbody></table></div><?php require '_footer.php'; ?>